import { Component } from '@angular/core';

@Component({
  selector: 'app-cta',
  templateUrl: './cta.component.html',
  styleUrls: ['./cta.component.css']
})
export class CtaComponent {

}
<section class="pixel-cta">
  <h2>¿Listo para empezar?</h2>
  <p>Contáctanos para discutir tu proyecto y descubrir cómo podemos ayudarte a alcanzar tus metas.</p>
  <button class="pixel-btn">Solicita una Cotización</button>
</section>
